      {
        "nombre": "Edición de imágenes (Image + Text-to-Image)",
        "descripcion": "Proporciona una imagen y utiliza prompts de texto para añadir, eliminar o modificar elementos, cambiar el estilo o ajustar la gradación de color.",
        "sub_modos": [
          "Añadir y eliminar elementos (Inpainting semántico): Modifica partes específicas de una imagen manteniendo el resto.",
          "Transferencia de estilo: Transforma una imagen al estilo artístico de otra."
        ]
      },
      {
        "nombre": "Composición Multi-Image a Image",
        "descripcion": "Utiliza múltiples imágenes de entrada para componer una nueva escena o transferir el estilo de una imagen a otra.",
        "sub_modos": [
          "Composición avanzada: Combina elementos de múltiples imágenes para crear una escena compuesta.",
          "Preservación de detalles de alta fidelidad: Asegura que los detalles críticos (como caras o logos) se conserven durante la edición."
        ]
      },
      {
        "nombre": "Refinamiento Iterativo",
        "descripcion": "Participa en una conversación para refinar progresivamente la imagen en múltiples turnos, haciendo pequeños ajustes."
      },
      {
        "nombre": "Renderizado de texto de alta fidelidad",
        "descripcion": "Genera imágenes con texto legible y bien posicionado, ideal para logos, diagramas y pósters."
